PHASES = ['vacuum','cooldown','energize','breakdown','ramp','flattop']
def cold_start(twin):
    for ph in PHASES:
        enter(ph)
        if not twin.converged(ph, timeout=phase_timeout[ph]):
            return safe_abort(ph)      # hold in last safe state
    return 'flattop_ok'

def flattop_supervise(state, twin):
    if twin.disruption_risk(state) > THRESH:
        return mitigate()               # see disruption page
    if twin.vertical_margin(state) < VMIN:
        boost_vertical_gain()
    log_neutron_yield(state)             # feeds TBR accounting 1.1/1.5/1.8
    return 'nominal'

def burner_hold(state, twin):
    if twin.plug_stress_ratio(state) > 1.0:      # design bore already 3-3.9x
        return derate('plug_stress')
    if not twin.fuel_available(state):           # He-3 supply gate
        return derate('fuel')
    if twin.confidence(state) < CONF_MIN:        # 166-830x regime -> low conf
        return 'hold_conservative'
    return 'export'

EDGES = {
  ('STANDBY','ARMED'): guard_interlocks_ready,
  ('ARMED','OPERATE'): guard_scenario_converged,
  ('OPERATE','DERATE'): guard_degradation_detected,
  ('DERATE','SAFING'): guard_limit_approaching,
  ('*','FAULT'): guard_protective_trip,   # always available
}
def step(cur, req, twin):
    g = EDGES.get((cur, req)) or EDGES.get(('*', req))
    return req if (g and g(twin)) else cur

from dataclasses import dataclass
