def sensor_trust(meas, redundant, twin_pred, tol_r, tol_m):
    disagree_r = abs(meas - redundant) > tol_r
    disagree_m = abs(meas - twin_pred) > tol_m
    if disagree_r and disagree_m:
        return 'suspect'     # this sensor likely wrong
    if disagree_r ^ disagree_m:
        return 'watch'
    return 'trusted'

import numpy as np
def fdi(meas, pred, cov_inv, signatures, chi2_thresh):
    r = meas - pred                      # residual vector
    score = float(r @ cov_inv @ r)       # normalized magnitude
    if score < chi2_thresh:
        return ('nominal', None)
    # isolate: nearest fault signature by direction
    best = max(signatures, key=lambda s: r @ s.direction / (np.linalg.norm(r)+1e-9))
    return ('fault', best.name)

class FailoverPair:
    def __init__(self, primary, standby, hb_timeout_ms):
        self.p, self.s, self.to = primary, standby, hb_timeout_ms
    def step(self, state):
        if self.p.heartbeat_age_ms() > self.to or self.p.faulted():
            self.s.promote(self.p.last_state())   # hot handover
            self.p, self.s = self.s, self.p
            flag('failover')
        return self.p.control(state)

def disruption_step(features, model, warn_ms_needed):
    p, ttd_ms = model.predict(features)   # prob, est time-to-disruption
    if p > P_HIGH and ttd_ms < warn_ms_needed:
        return trigger_mitigation()       # massive gas / shattered pellet
    if p > P_WATCH:
        return derate_scenario()          # back off toward safer point
    return 'nominal'

class Watchdog:
    def __init__(self, timeout_ms, on_timeout):
        self.to, self.cb, self.last = timeout_ms, on_timeout, now_ms()
    def pet(self): self.last = now_ms()
    def check(self):
        if now_ms() - self.last > self.to:
            self.cb()          # force failover or safe action
            return False
        return True

def maintenance_decision(rul_hours, next_opening_hours, safety_margin=1.5):
    # act at the opening only if RUL comfortably clears the following opening
    if rul_hours < next_opening_hours * safety_margin:
        return 'service_at_next_opening'
    return 'continue_monitor'

def anomaly_score(x, model):
    x_hat = model.reconstruct(x)
    return float(((x - x_hat) ** 2).mean())

def triage(score, warn, alarm):
    if score > alarm: return 'derate_and_review'
    if score > warn:  return 'flag_for_operator'
    return 'nominal'

def quench_detect(taps, L, dIdt, R_lead, I, thresh_V, persist_ms, dt_ms):
    V_res = taps.total() - (L * dIdt + R_lead * I)
    if V_res > thresh_V:
        quench_detect.count += dt_ms
    else:
        quench_detect.count = 0
    return quench_detect.count >= persist_ms   # require brief persistence
quench_detect.count = 0

def tile_damage(heat_flux_map, dt, fatigue_exp=4.0):
    # accumulate weighted thermal-fatigue damage per tile (Coffin-Manson-like)
    return (heat_flux_map ** fatigue_exp) * dt   # elementwise, worst tile drives RUL

from functools import reduce
def series(rs):    return reduce(lambda a, b: a * b, rs, 1.0)
def parallel(rs):  return 1.0 - reduce(lambda a, b: a * (1 - b), rs, 1.0)

# breeder magnet supply, no redundancy (series) vs redundant sensors (parallel)
print(series([0.99, 0.995, 0.98]))          # all must hold
print(parallel([0.9, 0.9, 0.9]))            # any one suffices

def effective_mttr(diagnose_h, procure_h, repair_h, verify_h, spare_on_hand):
    # a staged spare removes procurement lead time from the repair path
    procure = 0.0 if spare_on_hand else procure_h
    return diagnose_h + procure + repair_h + verify_h

def availability(mtbf_h, mttr_h):
    return mtbf_h / (mtbf_h + mttr_h)

from math import comb
def k_of_n(A_unit, n, k):
    # prob at least k of n units are up (independent)
    return sum(comb(n, i) * A_unit**i * (1-A_unit)**(n-i) for i in range(k, n+1))

print(k_of_n(0.95, n=4, k=3))   # facility-level uplift over a single 0.95 unit

def firm_power(unit_caps, reserve_units=1):
    # firm = total capacity minus the largest 'reserve_units' contributors
    caps = sorted(unit_caps, reverse=True)
    return sum(caps) - sum(caps[:reserve_units])

# with a stressed plug, a unit's cap is its DERATE point, not its design point
print(firm_power([80, 80, 80, 80], reserve_units=1))  # 240 firm from 320 available

def run_drill(twin, inject, expect):
    twin.reset(); twin.inject(inject)
    result = twin.run_until_settled()
    return {
      'detected_ms': result.detect_latency_ms <= expect.max_detect_ms,
      'response':    result.action == expect.action,
      'safe':        result.final_state in expect.safe_states,
    }
